import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cosine_sim_loss_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void cosine_sim_loss_kernel(
    const float* predictions,
    const float* targets,
    float* loss,
    int batch_size,
    int vec_size,
    float eps) {

    extern __shared__ float sdata[];

    int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const float* pred = predictions + batch_idx * vec_size;
    const float* targ = targets + batch_idx * vec_size;

    float dot = 0.0f;
    float norm_p = 0.0f;
    float norm_t = 0.0f;

    for (int i = threadIdx.x; i < vec_size; i += blockDim.x) {
        float p = pred[i];
        float t = targ[i];
        dot += p * t;
        norm_p += p * p;
        norm_t += t * t;
    }

    sdata[threadIdx.x] = dot;
    __syncthreads();
    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }
    dot = sdata[0];

    sdata[threadIdx.x] = norm_p;
    __syncthreads();
    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }
    norm_p = sdata[0];

    sdata[threadIdx.x] = norm_t;
    __syncthreads();
    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }
    norm_t = sdata[0];

    if (threadIdx.x == 0) {
        float norm_product = sqrtf(norm_p) * sqrtf(norm_t) + eps;
        float cos_sim = norm_product > 0.0f ? dot / norm_product : 0.0f;
        atomicAdd(loss, (1.0f - cos_sim) / batch_size);
    }
}

torch::Tensor cosine_sim_loss_cuda(torch::Tensor predictions, torch::Tensor targets, float eps) {
    predictions = predictions.contiguous();
    targets = targets.contiguous();
    int batch_size = predictions.size(0);
    int vec_size = predictions.size(1);
    auto loss = torch::zeros({1}, predictions.options());

    const int block_size = 256;
    dim3 grid(batch_size);
    size_t shared_mem_size = block_size * sizeof(float);

    cosine_sim_loss_kernel<<<grid, block_size, shared_mem_size>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<float>(),
        loss.data_ptr<float>(),
        batch_size,
        vec_size,
        eps
    );

    return loss;
}
"""

cosine_sim_loss_cpp_source = """
torch::Tensor cosine_sim_loss_cuda(torch::Tensor predictions, torch::Tensor targets, float eps);
"""

cosine_sim_loss = load_inline(
    name='cosine_sim_loss',
    cpp_sources=cosine_sim_loss_cpp_source,
    cuda_sources=cosine_sim_loss_source,
    functions=['cosine_sim_loss_cuda'],
    verbose=True,
    extra_cuda_cflags=['-O3']
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.cosine_sim_loss = cosine_sim_loss
        self.eps = 1e-8

    def forward(self, predictions, targets):
        return self.cosine_sim_loss.cosine_sim_loss_cuda(predictions.contiguous(), targets.contiguous(), self.eps)
